import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

const Recommendations = () => {
  const [recommendations, setRecommendations] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchRecommendations();
  }, []);

  const fetchRecommendations = async () => {
    try {
      const response = await axios.get(
        'http://localhost:5001/api/recommendations/for-user',
        {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        }
      );
      setRecommendations(response.data.recommendations);
    } catch (error) {
      console.error('Error fetching recommendations:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return (
    <div className="py-8 text-center">
      <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-black border-r-transparent"></div>
      <p className="mt-2 text-gray-600">Loading AI recommendations...</p>
    </div>
  );

  if (!recommendations || recommendations.length === 0) return null;

  return (
    <div className="bg-gradient-to-b from-gray-50 to-white rounded-2xl shadow-sm p-8 border border-gray-100">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-3xl font-bold" style={{ fontFamily: 'Playfair Display, serif' }}>
          Recommended For You
        </h2>
        <span className="text-sm bg-black text-white px-3 py-1 rounded-full">AI Powered</span>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {recommendations.map(product => (
          <Link 
            key={product._id} 
            to={`/product/${product._id}`}
            className="group bg-white border border-gray-200 rounded-xl overflow-hidden hover:shadow-xl transition-all duration-300"
          >
            <div className="aspect-square bg-gray-100 overflow-hidden">
              <img
                src={product.images?.[0] || 'https://via.placeholder.com/400'}
                alt={product.name}
                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
              />
            </div>
            <div className="p-4">
              <h3 className="font-semibold text-gray-800 mb-1 truncate">{product.name}</h3>
              <p className="text-xl font-bold text-black mb-3">${product.price}</p>
              <button 
                onClick={(e) => {
                  e.preventDefault();
                  alert('Added to cart!');
                }}
                className="w-full bg-black text-white py-2 rounded-lg hover:bg-gray-800 transition-colors text-sm"
              >
                Add to Cart
              </button>
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default Recommendations;
